#include <vector>
#include <iostream>

// Simulate an element that might throw on copy
struct ThrowingElement {
    int data;
    ThrowingElement(int d) : data(d) {}
    ThrowingElement(const ThrowingElement& other) {
        // Imagine conditional throw here (e.g., if memory pressure is high)
        data = other.data;
        // If an exception occurs, the vector must revert to original state
    }
};

int main() {
    std::vector<ThrowingElement> v;
    v.reserve(1); 
    // If a subsequent push_back triggers reallocation and the copy constructor 
    // throws, v.size() must not increase and v's contents must be intact.
    // The strong guarantee ensures container integrity upon failure.
}
